// Main App Component
const App = () => {
    const [userName, setUserName] = useState('');
    const [companyName, setCompanyName] = useState('');
    const [location, setLocation] = useState('');
    const [selectedPersona, setSelectedPersona] = useState(null);
    const [currentChallenge, setCurrentChallenge] = useState(null);
    const [userPrompt, setUserPrompt] = useState('');
    const [score, setScore] = useState(null);
    const [view, setView] = useState('userDetails'); // userDetails, personaSelection, challenge, scoring
    const [hasAgreed, setHasAgreed] = useState(false);

    useEffect(() => {
        if (score && view !== 'scoring') {
            setView('scoring');
        }
    }, [score, view]);

    const handleDetailsSubmit = () => {
        if (userName && companyName && location && hasAgreed) {
            setView('personaSelection');
        }
    };

    const handlePersonaSelect = (persona) => {
        setSelectedPersona(persona);
        const personaScenarios = personas[persona].scenarios;
        const randomIndex = Math.floor(Math.random() * personaScenarios.length);
        const challengeTemplate = personaScenarios[randomIndex];
        
        const challenge = {
            id: challengeTemplate.id,
            scenario: challengeTemplate.scenario.replace(/\[Company Name\]/g, companyName).replace(/\[Location\]/g, location),
            task: challengeTemplate.task.replace(/\[Company Name\]/g, companyName).replace(/\[Location\]/g, location),
            exampleSource: challengeTemplate.exampleSource
        };

        setUserPrompt('');
        setScore(null);
        setCurrentChallenge(challenge);
        setView('challenge');
    };

    const handleSubmitPrompt = () => {
        const newScore = scorePrompt(userPrompt, currentChallenge, selectedPersona, companyName, location);
        setScore(newScore);
    };

    const generateRecommendedPrompt = (challenge, persona, company, loc) => {
        const personaText = `Persona: As a ${persona} at ${company} in ${loc}.`;
        const taskText = `Task: ${challenge.task}`;
        const contextText = `Context: ${challenge.scenario}`;
        const formatText = `Format: Respond in a professional and clear format. The tone should be actionable and data-driven. Ensure the output is structured for easy presentation to leadership. Use ${challenge.exampleSource} as the source.`;

        return `${personaText}\n\n${taskText}\n\n${contextText}\n\n${formatText}`;
    };

    const scorePrompt = (prompt, challenge, persona, company, loc) => {
        let breakdown = {
            persona: { score: 0, max: 25, feedback: "The prompt does not clearly define the user's role or point of view." },
            task: { score: 0, max: 25, feedback: "The prompt's primary task isn't clearly stated." },
            context: { score: 0, max: 25, feedback: "Lacks background on why this is needed or who is involved." },
            format: { score: 0, max: 25, feedback: "Doesn't specify how the AI should respond (format, tone, style)." }
        };
        const p_lower = prompt.toLowerCase();
        
        // Persona Score
        const personaWords = ['as a', 'my role is', 'i am a', persona.toLowerCase()];
        if (personaWords.some(v => p_lower.includes(v))) breakdown.persona.score += 25;
        if (breakdown.persona.score > 15) breakdown.persona.feedback = "Excellent! You've clearly defined your persona.";
        
        // Task Score
        const taskVerbs = ['generate', 'create', 'write', 'analyze', 'summarize', 'devise', 'draft', 'outline', 'identify', 'compare', 'design', 'list', 'provide'];
        if (taskVerbs.some(v => p_lower.includes(v))) breakdown.task.score += 15;
        if (p_lower.split(' ').length > 10) breakdown.task.score += 10;
        breakdown.task.score = Math.min(25, breakdown.task.score);
        if (breakdown.task.score > 15) breakdown.task.feedback = "The prompt has a clear and specific task.";
        else if (breakdown.task.score > 5) breakdown.task.feedback = "The task is somewhat clear, but could be more specific.";

        // Context Score
        const contextWords = ['because', 'for', 'the situation is', company.toLowerCase()];
        if (contextWords.some(w => p_lower.includes(w))) breakdown.context.score += 25;
        if (breakdown.context.score > 15) breakdown.context.feedback = "Excellent context provided, explaining the 'why' and 'who'.";
        else if (breakdown.context.score > 5) breakdown.context.feedback = "Some context is present, but more detail would help.";

        // Format Score
        const formatWords = ['format', 'tone', 'style', 'respond in', 'act as', 'structure', 'in a', 'as a', 'no more than', 'source'];
        if (formatWords.some(w => p_lower.includes(w))) breakdown.format.score += 25;
        if (breakdown.format.score > 15) breakdown.format.feedback = "Clear expectations on format, tone, or style were set.";

        const total = breakdown.persona.score + breakdown.task.score + breakdown.context.score + breakdown.format.score;
        const recommendedPrompt = generateRecommendedPrompt(challenge, persona, company, loc);
        return { total, breakdown, recommendedPrompt };
    };

    const resetApp = () => {
        setView('userDetails');
        setSelectedPersona(null);
        setCurrentChallenge(null);
        setUserPrompt('');
        setScore(null);
        setUserName('');
        setCompanyName('');
        setLocation('');
        setHasAgreed(false);
    }
    
    const startOver = () => {
        setView('personaSelection');
        setSelectedPersona(null);
        setCurrentChallenge(null);
        setUserPrompt('');
        setScore(null);
    }

    const handleTryAgain = () => {
        setUserPrompt('');
        setScore(null);
        setView('challenge');
    }

    const renderContent = () => {
        switch (view) {
            case 'scoring':
                if (!score) return null; // Defensive check to prevent crash
                return <Scoring score={score} userName={userName} onTryAgain={handleTryAgain} onReset={startOver} />;
            case 'challenge':
                if (!currentChallenge) return null;
                return <Challenge persona={selectedPersona} scenario={currentChallenge.scenario} task={currentChallenge.task} userPrompt={userPrompt} setUserPrompt={setUserPrompt} onSubmit={handleSubmitPrompt} onBack={startOver} />;
            case 'personaSelection':
                return <PersonaSelector personas={Object.keys(personas)} onSelect={handlePersonaSelect} userName={userName} />;
            case 'userDetails':
            default:
                return <WelcomePage 
                            nickname={userName} 
                            setNickname={setUserName} 
                            companyName={companyName} 
                            setCompanyName={setCompanyName} 
                            location={location} 
                            setLocation={setLocation} 
                            hasAgreed={hasAgreed} 
                            setHasAgreed={setHasAgreed} 
                            onProceed={() => setView('personaSelection')} 
                        />;
        }
    }

    return (
        <div className="bg-slate-900 min-h-screen text-white font-sans flex items-center justify-center p-4">
            <div className="w-full max-w-4xl mx-auto">
                <header className="text-center mb-8">
                    <h1 className="text-4xl md:text-5xl font-bold text-cyan-400">PromptCraft Challenge</h1>
                    <p className="text-slate-400 mt-2">Hone your AI prompting skills through randomized, real-world scenarios.</p>
                </header>
                <main className="bg-slate-800 rounded-2xl shadow-2xl shadow-cyan-500/10 p-6 md:p-10 transition-all duration-500 ease-in-out min-h-[400px]">
                    {renderContent()}
                </main>
                 <footer className="text-center mt-8 text-slate-500 text-sm">
                    <p>Challenger: {userName || 'a user'} from {companyName || 'a company'} | <button onClick={resetApp} className="underline hover:text-cyan-400">Reset All</button></p>
                </footer>
            </div>
        </div>
    );
};

