// Scoring Component
const Scoring = ({ score, userName, onTryAgain, onReset }) => {
    const resultsRef = useRef(null);

    const handleDownloadImage = () => {
        if (!resultsRef.current || !window.html2canvas) return;
        window.html2canvas(resultsRef.current, { backgroundColor: '#1e293b' }).then((canvas) => {
            const link = document.createElement('a');
            link.download = 'prompt-challenge-results.png';
            link.href = canvas.toDataURL('image/png');
            link.click();
        });
    };

    const handleDownloadPDF = () => {
        if (!resultsRef.current || !window.html2canvas || !window.jspdf) return;
        const { jsPDF } = window.jspdf;
        window.html2canvas(resultsRef.current, { backgroundColor: '#1e293b' }).then((canvas) => {
            const imgData = canvas.toDataURL('image/png');
            const pdf = new jsPDF({
                orientation: 'portrait',
                unit: 'px',
                format: [canvas.width, canvas.height]
            });
            pdf.addImage(imgData, 'PNG', 0, 0, canvas.width, canvas.height);
            pdf.save('prompt-challenge-results.pdf');
        });
    };

    const getScoreColor = (s, max) => {
        const percentage = (s / max) * 100;
        if (percentage >= 80) return 'text-green-400';
        if (percentage >= 60) return 'text-sky-400';
        if (percentage >= 30) return 'text-yellow-400';
        return 'text-red-400';
    };

    const getScoreFeedback = (s) => {
        if (s >= 80) return `Well done, ${userName}!`;
        if (s >= 60) return `Good job, ${userName}!`;
        if (s >= 30) return `You're getting better at this, ${userName}!`;
        return `You can improve, ${userName}. Practice more!`;
    };

    const ScoreBar = ({ label, value, maxValue, feedback }) => {
        const percentage = (value / maxValue) * 100;
        return (
            <div className="mb-4">
                <div className="flex justify-between items-end mb-1">
                    <span className="font-semibold text-slate-300">{label}</span>
                    <span className={`font-bold ${getScoreColor(value, maxValue)}`}>{value}/{maxValue}</span>
                </div>
                <div className="w-full bg-slate-700 rounded-full h-2.5">
                    <div className={`h-2.5 rounded-full ${getScoreColor(value, maxValue).replace('text','bg')}`} style={{ width: `${percentage}%` }}></div>
                </div>
                 <p className="text-xs text-slate-400 mt-1 italic">{feedback}</p>
            </div>
        );
    };

    return (
        <div className="animate-fade-in">
            <div ref={resultsRef} className="bg-slate-800 p-8">
                <h2 className="text-3xl font-bold text-center text-cyan-400 mb-4">Your Score</h2>
                <div className="text-center mb-6">
                    <div className={`inline-block p-6 bg-slate-900/50 rounded-full border-4 ${getScoreColor(score.total, 100).replace('text', 'border')}`}>
                        <span className={`text-6xl font-bold ${getScoreColor(score.total, 100)}`}>{score.total}</span>
                        <span className="text-2xl text-slate-400">/100</span>
                    </div>
                    <p className="text-slate-300 font-semibold mt-3 text-xl">{getScoreFeedback(score.total)}</p>
                </div>

                <div className="grid lg:grid-cols-2 gap-8 mb-8">
                    <div className="bg-slate-900/50 p-6 rounded-lg">
                        <h3 className="text-xl font-semibold mb-4 text-white">Score Breakdown</h3>
                        <ScoreBar label="Persona" value={score.breakdown.persona.score} maxValue={25} feedback={score.breakdown.persona.feedback} />
                        <ScoreBar label="Task" value={score.breakdown.task.score} maxValue={25} feedback={score.breakdown.task.feedback} />
                        <ScoreBar label="Context" value={score.breakdown.context.score} maxValue={25} feedback={score.breakdown.context.feedback} />
                        <ScoreBar label="Format" value={score.breakdown.format.score} maxValue={25} feedback={score.breakdown.format.feedback} />
                    </div>

                    <div className="bg-slate-900/50 p-6 rounded-lg">
                        <h3 className="text-xl font-semibold mb-4 text-white">Better Prompt Recommendation</h3>
                        <div className="bg-slate-900 p-4 rounded-md whitespace-pre-wrap text-slate-300 text-sm">
                            {score.recommendedPrompt}
                        </div>
                    </div>
                </div>
            </div>

            <div className="mt-8 text-center">
                <h3 className="text-xl font-semibold mb-4 text-white">Download Results</h3>
                <div className="flex justify-center gap-4 flex-wrap mb-6">
                     <button onClick={handleDownloadImage} className="bg-sky-500 text-white font-bold py-2 px-5 rounded-lg hover:bg-sky-600 transform hover:scale-105 transition-transform duration-300">Download as Image (.png)</button>
                     <button onClick={handleDownloadPDF} className="bg-sky-500 text-white font-bold py-2 px-5 rounded-lg hover:bg-sky-600 transform hover:scale-105 transition-transform duration-300">Download as PDF</button>
                </div>
                <div className="flex justify-center gap-4 flex-wrap">
                    <button onClick={onTryAgain} className="bg-slate-600 text-white font-bold py-3 px-6 rounded-lg hover:bg-slate-500 transform hover:scale-105 transition-transform duration-300">Try Again</button>
                    <button onClick={onReset} className="bg-cyan-500 text-slate-900 font-bold py-3 px-6 rounded-lg hover:bg-cyan-400 transform hover:scale-105 transition-transform duration-300">New Challenge</button>
                </div>
            </div>
        </div>
    );
};

